export function getThemeById(id: string): ThemeItem | undefined {
  return themes.find((t) => t.id === id)
}

/** 표시 테마 수 N: 상승 상위 ceil(N/2) + 하락 하위 floor(N/2) */
export function selectTreemapThemes(count: number): ThemeItem[] {
  const ups = themes.filter((t) => t.change > 0).sort((a, b) => b.change - a.change)
  const downs = themes.filter((t) => t.change < 0).sort((a, b) => a.change - b.change)
  return [...ups.slice(0, Math.ceil(count / 2)), ...downs.slice(0, Math.floor(count / 2))]
}
